-- 447_hidden_curated_5.sql — #447 San Antonio, part 2e: 25 gate rescues for HIDDEN storyless pins that step (5)'s gate dry run
-- dropped (447_gate_drops_san_antonio.tsv). A curated row under the pin's EXACT stored name at its stored coordinate brings the
-- pin back with its story (handoff §6 story-lines (y)); every pin passed #542 (its containing tile, by Math.round, stores it),
-- checked by pin id across every stored row. Stories: the marker inscriptions on HMdb, read from bash (each marker matched by
-- title within 31 m of the pin; 22 of 24 within 2 m), and Wikipedia for F.I.S.H. Every number and capitalised name was checked
-- against its source text (the marker's own title supplies the subject's name). Batch file — run in the same Mac session as the
-- batch's names files, then curated_category_backfill(true); every row should report dist_m 0.
-- WITHIN 30 m WITH A REASON: separate grave markers side by side in a cemetery — Charles Frederick King / Samuel S. Smith 6 m,
-- James Nathaniel Fisk / Simona Smith Fisk 3 m (husband and wife). Neither row is a grave pin: the grave pass loaded none of them.
with v(name, lat, lng, description, source_url, note) as (values
  ($t$"Kelly No. 2" Flight Line$t$, 29.3845099::double precision, -98.5741907::double precision, $t$In September 1917 Kelly Field's flight training moved north to this area, called "Kelly No. 2" to set it apart from the original field, and its flight line of hangars, warehouses, barracks, repair shops and classrooms ran 125 yards east and 2400 yards west of this spot.$t$, $t$https://www.hmdb.org/m.asp?m=65285$t$, $t$#447 gate rescue (part 2e): osm_node5248071930, stored in 588_-1971, 588_-1972; containing tile 588_-1971 stores it (#542)$t$),
  ($t$Charles Frederick King$t$, 29.42062::double precision, -98.46718::double precision, $t$Charles Frederick King, born in New Hampshire in 1811, served in the Texas Army in 1836 and was mayor of San Antonio in 1847-1849 and again in 1852-1853; he died in San Antonio in 1869.$t$, $t$https://www.hmdb.org/m.asp?m=177381$t$, $t$#447 gate rescue (part 2e): osm_node12395077380, stored in 588_-1969; containing tile 588_-1969 stores it (#542)$t$),
  ($t$Dawson Massacre$t$, 29.4996::double precision, -98.42266::double precision, $t$Near here on September 18, 1842, Captain Nicholas Mosby Dawson and 53 men from La Grange, trying to join Captain Mathew Caldwell's Texas volunteers at the Battle of the Salado, were surrounded by Mexican forces: 36 were killed, 15 were taken prisoner and only 3 escaped.$t$, $t$https://www.hmdb.org/m.asp?m=85981$t$, $t$#447 gate rescue (part 2e): osm_node12395184233, stored in 590_-1968, 590_-1969; containing tile 590_-1968 stores it (#542)$t$),
  ($t$Dodd Field (Fort Sam Houston) Enemy Alien Detention Station, World War II$t$, 29.4785::double precision, -98.43101::double precision, $t$From April 1942 the post's former airfield, Dodd Field, was a U.S. Army detention station for Japanese, German and Italian nationals held as enemy aliens: 20 acres inside a double barbed-wire fence with eight guard towers over two compounds of Victory Huts, never holding more than 150 people at a time, until it closed in late 1942.$t$, $t$https://www.hmdb.org/m.asp?m=206869$t$, $t$#447 gate rescue (part 2e): osm_node12395077346, stored in 590_-1968, 590_-1969; containing tile 590_-1969 stores it (#542)$t$),
  ($t$In this vicinity the Battle of Rosillo$t$, 29.35723::double precision, -98.40968::double precision, $t$In this vicinity on March 28, 1813, the "Republican Army of the North" of Anglo-Americans, Mexicans and Indians defeated Spanish Royalist troops under Manuel de Salcedo, Governor of Texas, with heavy loss of life, and the prisoners were brutally murdered soon afterward on the order of Colonel Bernardo Gutierrez.$t$, $t$https://www.hmdb.org/m.asp?m=300113$t$, $t$#447 gate rescue (part 2e): osm_node13971413909, stored in 587_-1968, 587_-1969; containing tile 587_-1968 stores it (#542)$t$),
  ($t$James Nathaniel Fisk$t$, 29.42057::double precision, -98.46885::double precision, $t$James Nathaniel Fisk, born in Swanton, Vermont, in 1815, served in the Army of Texas from March 6, 1836, to November 16, 1837, and died in 1876.$t$, $t$https://www.hmdb.org/m.asp?m=237182$t$, $t$#447 gate rescue (part 2e): osm_node12395077310, stored in 588_-1969; containing tile 588_-1969 stores it (#542)$t$),
  ($t$Simona Smith Fisk$t$, 29.42054::double precision, -98.46885::double precision, $t$Simona Smith Fisk, born in San Antonio in 1829, was the daughter of Erastus "Deaf" Smith and the wife of James Nathaniel Fisk; she died in 1890.$t$, $t$https://www.hmdb.org/m.asp?m=208481$t$, $t$#447 gate rescue (part 2e): osm_node12395077335, stored in 588_-1969; containing tile 588_-1969 stores it (#542)$t$),
  ($t$Jefferson Davis Smith$t$, 29.55589::double precision, -98.4926::double precision, $t$Jefferson Davis Smith was 9 when he and his brother Clint, 11, were kidnapped by Lipan and Comanche Indians while herding sheep near their Kendall County home in 1871; Jeff was reportedly bought by the Apache chief Geronimo, returned to his family by Mexican bandits for a $1,000 reward about 1878, and later moved to San Antonio.$t$, $t$https://www.hmdb.org/m.asp?m=177107$t$, $t$#447 gate rescue (part 2e): osm_node12395077383, stored in 591_-1969, 591_-1970; containing tile 591_-1970 stores it (#542)$t$),
  ($t$John "Jack" Coker$t$, 29.55637::double precision, -98.49263::double precision, $t$John "Jack" Coker came from South Carolina in 1834, fought at San Jacinto, and was in the party with Deaf Smith that destroyed Vince's bridge, which may have kept Santa Anna's army from retreat or reinforcement; Texas awarded him 1,920 acres, where he and his brother Joseph founded the Coker community.$t$, $t$https://www.hmdb.org/m.asp?m=177129$t$, $t$#447 gate rescue (part 2e): osm_node12395077381, stored in 591_-1969, 591_-1970; containing tile 591_-1970 stores it (#542)$t$),
  ($t$Lockhill School$t$, 29.56586::double precision, -98.5834::double precision, $t$One of Texas' oldest public schools, operating continuously since 1868, this school was named for Wm. J. Locke, who donated the land; it first met in a supply depot, was called "Shavano" for some years, and the present building dates from 1923.$t$, $t$https://www.hmdb.org/m.asp?m=176039$t$, $t$#447 gate rescue (part 2e): osm_node12395077397, stored in 591_-1971, 591_-1972; containing tile 591_-1972 stores it (#542)$t$),
  ($t$Lydia Mendoza$t$, 29.41752::double precision, -98.54737::double precision, $t$Houston native Lydia Mendoza, "La Alondra de la Frontera," was one of the first and most famous singers of the Texas-Mexico border; her 1934 recording of "Mal Hombre" launched a decades-long career that brought her the National Medal of Arts in 1999 and a U.S. postage stamp in 2013.$t$, $t$https://www.hmdb.org/m.asp?m=150255$t$, $t$#447 gate rescue (part 2e): osm_node12395184219, stored in 588_-1971, 589_-1971; containing tile 588_-1971 stores it (#542)$t$),
  ($t$Olde Espada Dam Marker$t$, 29.3462898::double precision, -98.4656127::double precision, $t$Built sometime between 1731 and 1745 on natural rock, Espada Dam is the oldest continuously used Spanish-built diversion dam in Texas; its unusual reverse buttress has withstood centuries of floods, and it still sends about 4500 gallons a minute into the 4-mile Acequia de Espada to water 400 acres near Mission San Francisco de la Espada.$t$, $t$https://www.hmdb.org/m.asp?m=213283$t$, $t$#447 gate rescue (part 2e): osm_node3576187813, stored in 587_-1969, 587_-1970; containing tile 587_-1969 stores it (#542)$t$),
  ($t$Route of El Camino Real$t$, 29.51526::double precision, -98.45361::double precision, $t$The Camino Real, or King's Highway, followed ancient Indian and buffalo trails 1,000 miles from Mexico to present Louisiana; San Antonio was a major stop, Moses Austin followed it here in 1820, and in 1915 the Texas Legislature set aside $5,000 to mark the road across the state with granite markers every five miles.$t$, $t$https://www.hmdb.org/m.asp?m=130099$t$, $t$#447 gate rescue (part 2e): osm_node12395184221, stored in 590_-1969, 591_-1969; containing tile 590_-1969 stores it (#542)$t$),
  ($t$Saint Philip's Episcopal Church$t$, 29.40213::double precision, -98.43255::double precision, $t$Established in 1895 as the first Episcopal church for African Americans in the Diocese of West Texas, St. Philip's began in an old German Methodist church in what became La Villita and started a vocational school in 1898 that became St. Philip's College; the congregation built this church on Pecan Valley Drive in 1963.$t$, $t$https://www.hmdb.org/m.asp?m=207911$t$, $t$#447 gate rescue (part 2e): osm_node12395077343, stored in 588_-1968, 588_-1969; containing tile 588_-1969 stores it (#542)$t$),
  ($t$Samuel S. Smith$t$, 29.42062::double precision, -98.46712::double precision, $t$Samuel S. Smith, born in Boston in 1810, was a member of the Woll and Somervell expeditions of 1842 and died in 1882; his wife, Sarah Brackett Smith, born in New York in 1836, died in 1901.$t$, $t$https://www.hmdb.org/m.asp?m=177383$t$, $t$#447 gate rescue (part 2e): osm_node12395077379, stored in 588_-1969; containing tile 588_-1969 stores it (#542)$t$),
  ($t$Site of the Camp of Stephen F. Austin$t$, 29.39834::double precision, -98.42494::double precision, $t$Stephen F. Austin camped here while assembling troops for the attack on the Mexican garrison at San Antonio; after his appointment on November 12 as commissioner to the United States, the Texans under Colonels Ben Milam and Frank W. Johnson stormed and captured the town on December 10, 1835.$t$, $t$https://www.hmdb.org/m.asp?m=207943$t$, $t$#447 gate rescue (part 2e): osm_node12395077342, stored in 588_-1968, 588_-1969; containing tile 588_-1968 stores it (#542)$t$),
  ($t$Spanish and Mexican Land Grants$t$, 29.3039999::double precision, -98.5248126::double precision, $t$The Texas A&M University-San Antonio campus stands on land once conveyed by Spanish and Mexican grants — the earliest to Mission San Jose y San Miguel de Aguayo in 1720 — and much of it lies on the grant to Fernando Rodriguez, son-in-law of the cattleman Juan Ignacio Perez, who received a five-league grant on the Medina River in 1808.$t$, $t$https://www.hmdb.org/m.asp?m=98241$t$, $t$#447 gate rescue (part 2e): osm_node12395184231, stored in 586_-1970, 586_-1971; containing tile 586_-1970 stores it (#542)$t$),
  ($t$Station "X"$t$, 29.38218::double precision, -98.56976::double precision, $t$In 1942 the San Antonio Air Depot sent 1,050 civilian aircraft specialists, mostly Texans, to an overseas post they knew only as Station "X" — the Burtonwood depot near Warrington, England — where they helped modify or overhaul 11,757 aircraft under the motto "Keep 'em Flying!"$t$, $t$https://www.hmdb.org/m.asp?m=207892$t$, $t$#447 gate rescue (part 2e): osm_node12395077344, stored in 587_-1971, 588_-1971; containing tile 588_-1971 stores it (#542)$t$),
  ($t$Sunshine Ranch$t$, 29.47685::double precision, -98.54825::double precision, $t$For 50 years this was Sunshine Ranch, given in 1905 to Albert and Jane (Maury) Maverick; their son Jim Maverick opened the Sunshine Dairy in 1917, selling Sunshine certified milk, cream and cottage cheese that Joske's used for its ice cream, until the city annexed the land in 1955 and it became a subdivision.$t$, $t$https://www.hmdb.org/m.asp?m=176050$t$, $t$#447 gate rescue (part 2e): osm_node12395077396, stored in 589_-1971, 590_-1971; containing tile 590_-1971 stores it (#542)$t$),
  ($t$Texas' First All-Spanish Radio Program$t$, 29.45311::double precision, -98.56239::double precision, $t$On October 28, 1928, "Radio Sam" (KGCI, now KMAC) began a two-hour nightly program entirely in Spanish, Texas' first, produced and announced by Julian F. Lozano from studios at St. Mary's University.$t$, $t$https://www.hmdb.org/m.asp?m=294968$t$, $t$#447 gate rescue (part 2e): osm_node13971413915, stored in 589_-1971, 589_-1972; containing tile 589_-1971 stores it (#542)$t$),
  ($t$Berg's Mill$t$, 29.3353847::double precision, -98.4564992::double precision, $t$Mills on the San Antonio River near here, beginning in the middle 1800s, grew into a small community named Berg's Mill for millers Henry and Louis Berg, who lost their wool mill and cotton gin to foreclosure in 1889; by the early 1930s the community had a railroad station, post office, movie theater and school.$t$, $t$https://www.hmdb.org/m.asp?m=213431$t$, $t$#447 gate rescue (part 2e): osm_way120248304, stored in 586_-1969, 587_-1969; containing tile 587_-1969 stores it (#542)$t$),
  ($t$Hugman Dam$t$, 29.431808::double precision, -98.4879062::double precision, $t$Here at the northern end of architect Robert H.H. Hugman's River Walk, dedicated before a crowd of fifty thousand on April 21, 1941, water spilled over a small stone and concrete weir and river cruises boarded just above the Fourth Street Bridge; the weir was modified in 2008 to let barges move upstream.$t$, $t$https://www.hmdb.org/m.asp?m=119898$t$, $t$#447 gate rescue (part 2e): osm_node2982236797, stored in 588_-1970, 589_-1969, 589_-1970; containing tile 589_-1970 stores it (#542)$t$),
  ($t$John F Kennedy Memorial Tree$t$, 29.3462669::double precision, -98.4651469::double precision, $t$This thornless honeylocust from the Kennedy estate at Hyannisport, Massachusetts, was given to the San Antonio River Authority through Senator Edward M. Kennedy and planted on April 24, 1966, in memory of President John F. Kennedy.$t$, $t$https://www.hmdb.org/m.asp?m=213280$t$, $t$#447 gate rescue (part 2e): osm_node6986053452, stored in 587_-1969, 587_-1970; containing tile 587_-1969 stores it (#542)$t$),
  ($t$King's Highway Monument$t$, 29.320908::double precision, -98.4552665::double precision, $t$The Daughters of the American Revolution and the State of Texas set this monument in 1918 to mark the Kings Highway — the Camino Real, or Old San Antonio Road.$t$, $t$https://www.hmdb.org/m.asp?m=223013$t$, $t$#447 gate rescue (part 2e): osm_node1355557574, stored in 586_-1969, 587_-1969; containing tile 586_-1969 stores it (#542)$t$),
  ($t$F.I.S.H.$t$, 29.4396354::double precision, -98.4816877::double precision, $t$Donald Lipski's 2009 sculpture hangs a school of 25 hand-painted, anatomically correct long-eared sunfish, each 7 feet long, under the I-35 overpass on the San Antonio River, with one more fish inside The DoSeum children's museum.$t$, $t$https://en.wikipedia.org/wiki/F.I.S.H.$t$, $t$#447 gate rescue (part 2e): osm_node937414664, stored in 589_-1969, 589_-1970; containing tile 589_-1970 stores it (#542)$t$)
)
insert into public.curated_descriptions (name, lat, lng, description, source_url, note)
select v.name, v.lat, v.lng, v.description, v.source_url, v.note
from v
where not exists (
  select 1 from public.curated_descriptions d
  where d.name_clean = regexp_replace(lower(v.name), '[^a-z0-9]', '', 'g')
    and 6371000 * sqrt(
          power(radians(d.lat - v.lat), 2) +
          power(cos(radians((d.lat + v.lat) / 2)) * radians(d.lng - v.lng), 2)) <= 50
)
returning name, note;
